// Du lieu 296 dau viec lay tu file "SO LAM VIEC SO 01" (phan 1: dau viec 1-148).
// Moi dong la mot dau viec (cap 3) gan voi vi tri thuc thi + RACI theo vai tro.
// Cac truong text (input/output/kpi/sla/nguong) giu gan nguyen van file goc.

export type KieuRaci = readonly (readonly ['R' | 'A' | 'C' | 'I',
  'ceo' | 'tp' | 'tn' | 'nv_cv' | 'tbks'])[];
export type MucDo = 'cao' | 'rat_cao' | 'trung_binh';

export interface DongDauViec {
  /** Ma vi tri thuc thi (xem CAC_VI_TRI). */
  vt: string;
  ten: string;
  /** Ma nhom trach nhiem cap 1. */
  nhom: string;
  /** Ma tn chi tiet cap 2; null = khoi "(chua gan)". */
  tn: string | null;
  /** Ten phong ban; null = ap dung toan cong ty / moi phong. */
  phong: string | null;
  vao: string | null;
  ra: string | null;
  kpi: string | null;
  co_bc: boolean;
  ma_bc: string | null;
  tt_bc: 'de_xuat' | 'chuan' | null;
  /** Tan suat chuan hoa de sinh viec dinh ky. */
  ts: 'hang_ngay' | 'hang_tuan' | 'hai_tuan' | 'hang_thang' | 'hang_quy' | 'hang_nam'
    | '6_thang' | 'phat_sinh' | 'lien_tuc';
  /** Tan suat tho goc trong file. */
  ts_tho: string;
  sla: string | null;
  /** Nguong phan cap xu ly (neu co). */
  ng: string | null;
  md: MucDo;
  /** Ghi chu (vd can review). */
  gc: string | null;
  raci: KieuRaci;
}

/** Ngan gon de tao mot dong dau viec. */
export function dv(d: DongDauViec): DongDauViec { return d; }

